#include <string.h> // Required for strlen, strstr, strcmp, strncpy, strchr, strcpy, strcat
#include <stdlib.h> // Required for malloc, free

/**
Check if the provided target URL string is within the provided domain.
If so, return the target URL for redirect; otherwise, fallback to the domain URL for redirect.
Use https protocol.

Examples:
    get_target_for_redirect("https://music.example.com", "example.com") -> "https://music.example.com"
    get_target_for_redirect("https://example.com/service", "example.com") -> "https://example.com/service"
    get_target_for_redirect("https://blog.example.com/posts", "example.com") -> "https://blog.example.com/posts"
    get_target_for_redirect("https://another.com", "example.com") -> "https://example.com"

@param target: The target URL string.
@param domain: The domain string, without protocol.

@return The URL string for redirect.
*/
char* get_target_for_redirect(const char* target, const char* domain) {
    // --- Prepare the fallback URL (https://domain) ---
    const char* https_prefix = "https://";
    size_t domain_len = strlen(domain);
    size_t fallback_url_len = strlen(https_prefix) + domain_len;

    // Allocate memory for the fallback URL.
    // As per problem statement, we assume this allocation succeeds.
    char* fallback_url = (char*)malloc(fallback_url_len + 1);
    // In a real-world scenario, one would check if (!fallback_url) and handle the error.
    // For this problem, we proceed assuming success.
    strcpy(fallback_url, https_prefix);
    strcat(fallback_url, domain);

    // --- Parse the target URL to extract its hostname ---
    const char* protocol_end = strstr(target, "://");
    if (!protocol_end) {
        // If no protocol separator is found, the target URL is malformed or not in the expected format.
        // In this case, we fallback to the domain URL.
        return fallback_url;
    }

    const char* host_start = protocol_end + 3; // Move past "://"

    // Find the end of the hostname (before path, query, fragment, or end of string)
    const char* host_end = host_start;
    while (*host_end != '\0' && *host_end != '/' && *host_end != '?' && *host_end != '#') {
        host_end++;
    }

    // Check for an optional port number (e.g., example.com:8080)
    const char* port_separator = strchr(host_start, ':');
    size_t hostname_len;
    if (port_separator && port_separator < host_end) {
        // A port is present, so the hostname is the part before the colon
        hostname_len = port_separator - host_start;
    } else {
        // No port, the hostname is the entire segment up to host_end
        hostname_len = host_end - host_start;
    }

    // Allocate memory for the extracted hostname
    // As per problem statement, we assume this allocation succeeds.
    char* extracted_hostname = (char*)malloc(hostname_len + 1);
    // In a real-world scenario, one would check if (!extracted_hostname).
    strncpy(extracted_hostname, host_start, hostname_len);
    extracted_hostname[hostname_len] = '\0'; // Null-terminate the extracted hostname

    // --- Compare the extracted hostname with the provided domain ---
    size_t extracted_len = strlen(extracted_hostname);
    int is_within_domain = 0;

    if (extracted_len == domain_len) {
        // Exact match (e.g., "example.com" vs "example.com")
        if (strcmp(extracted_hostname, domain) == 0) {
            is_within_domain = 1;
        }
    } else if (extracted_len > domain_len) {
        // Potential subdomain (e.g., "music.example.com" vs "example.com")
        // Check if the extracted hostname ends with ".domain"
        // Ensure there's a '.' right before the domain part in the extracted hostname
        if (extracted_hostname[extracted_len - domain_len - 1] == '.') {
            if (strcmp(extracted_hostname + (extracted_len - domain_len), domain) == 0) {
                is_within_domain = 1;
            }
        }
    }

    // Free the temporary extracted hostname memory
    free(extracted_hostname);

    // --- Determine the final URL to return ---
    if (is_within_domain) {
        // The target URL is within the domain. Return a copy of the original target URL.
        size_t target_len = strlen(target);
        // As per problem statement, we assume this allocation succeeds.
        char* result_target = (char*)malloc(target_len + 1);
        // In a real-world scenario, one would check if (!result_target).
        strcpy(result_target, target);
        free(fallback_url); // Free the fallback_url as it's not being used.
        return result_target;
    } else {
        // The target URL is not within the domain. Return the prepared fallback URL.
        return fallback_url;
    }
}
